-- 038_ranking_motor_migracion.sql
-- Snapshot de RANKING/CONFIGURACION_RANKING + motor deterministico PostgreSQL.
-- Julio/agosto se conservan como historico publicado. Septiembre usa configuracion objetivo de migracion.

create table if not exists public.ranking_legacy_snapshot (
  source_row integer not null,
  id text primary key,
  periodo text not null,
  cuadrilla text not null,
  usuario text,
  sede text,
  plataforma text,
  produccion numeric not null default 0,
  efectividad numeric not null default 0,
  recableado numeric not null default 0,
  vtrgar numeric not null default 0,
  observaciones integer not null default 0,
  monto_total numeric not null default 0,
  monto_afectado numeric not null default 0,
  puntaje_final numeric not null default 0,
  puesto_sede integer not null default 0,
  puesto_region integer not null default 0,
  puesto_plataforma integer not null default 0,
  medalla_region text,
  medalla_sede text,
  medalla_plataforma text,
  sla_bruto numeric not null default 0,
  sla_ajustado numeric not null default 0,
  sla_evaluables integer not null default 0,
  sla_fuera integer not null default 0,
  sla_excepciones_aprobadas integer not null default 0,
  aporte_sla numeric not null default 0,
  pesos_json jsonb not null default '{}'::jsonb,
  imported_at timestamptz not null default now()
);

create table if not exists public.ranking_configuracion_productiva_snapshot (
  periodo text primary key,
  produccion_pct numeric not null,
  efectividad_pct numeric not null,
  sla_pct numeric not null,
  observaciones_pct numeric not null,
  recableado_pct numeric not null,
  vtrgar_pct numeric not null,
  total_pct numeric not null,
  estado text,
  actualizado_por text,
  fecha_actualizacion text,
  imported_at timestamptz not null default now()
);

create table if not exists public.ranking_configuracion_motor (
  periodo text primary key,
  produccion_pct numeric not null,
  efectividad_pct numeric not null,
  sla_pct numeric not null,
  observaciones_pct numeric not null,
  recableado_pct numeric not null,
  vtrgar_pct numeric not null,
  total_pct numeric generated always as
    (produccion_pct+efectividad_pct+sla_pct+observaciones_pct+recableado_pct+vtrgar_pct) stored,
  estado text not null default 'ACTIVO',
  origen text not null,
  actualizado_por text,
  actualizado_at timestamptz not null default now(),
  constraint ranking_config_motor_total_100 check
    (produccion_pct+efectividad_pct+sla_pct+observaciones_pct+recableado_pct+vtrgar_pct=100)
);

truncate table public.ranking_legacy_snapshot;
insert into public.ranking_legacy_snapshot (
  source_row,id,periodo,cuadrilla,usuario,sede,plataforma,produccion,efectividad,recableado,vtrgar,
  observaciones,monto_total,monto_afectado,puntaje_final,puesto_sede,puesto_region,puesto_plataforma,
  medalla_region,medalla_sede,medalla_plataforma,sla_bruto,sla_ajustado,sla_evaluables,sla_fuera,
  sla_excepciones_aprobadas,aporte_sla,pesos_json
)
