  periodo,produccion_pct,efectividad_pct,sla_pct,observaciones_pct,recableado_pct,vtrgar_pct,total_pct,
  estado,actualizado_por,fecha_actualizacion
)
select periodo,produccion_pct,efectividad_pct,sla_pct,observaciones_pct,recableado_pct,vtrgar_pct,total_pct,
       estado,actualizado_por,fecha_actualizacion
from jsonb_to_recordset('[{"periodo":"2026-07","produccion_pct":35,"efectividad_pct":30,"sla_pct":0,"observaciones_pct":10,"recableado_pct":12.5,"vtrgar_pct":12.5,"total_pct":100,"estado":"CERRADO","actualizado_por":"SISTEMA","fecha_actualizacion":"06/08/2026"},{"periodo":"2026-08","produccion_pct":30,"efectividad_pct":20,"sla_pct":15,"observaciones_pct":15,"recableado_pct":10,"vtrgar_pct":10,"total_pct":100,"estado":"ACTIVO","actualizado_por":"SISTEMA","fecha_actualizacion":"06/08/2026"},{"periodo":"2026-09","produccion_pct":50,"efectividad_pct":20,"sla_pct":5,"observaciones_pct":5,"recableado_pct":5,"vtrgar_pct":15,"total_pct":100,"estado":"ACTIVO","actualizado_por":"JEFATURA - SOLICITUD CHAT 16/09/2026","fecha_actualizacion":"16/09/2026"}]'::jsonb) as x(
  periodo text,produccion_pct numeric,efectividad_pct numeric,sla_pct numeric,observaciones_pct numeric,
  recableado_pct numeric,vtrgar_pct numeric,total_pct numeric,estado text,actualizado_por text,fecha_actualizacion text
);

insert into public.ranking_configuracion_motor (
  periodo,produccion_pct,efectividad_pct,sla_pct,observaciones_pct,recableado_pct,vtrgar_pct,estado,origen,actualizado_por
) values ('2026-09',40,20,10,10,10,10,'ACTIVO','MIGRACION_OBJETIVO','JEFATURA - OBJETIVO MIGRACION')
on conflict (periodo) do update set
  produccion_pct=excluded.produccion_pct,
  efectividad_pct=excluded.efectividad_pct,
  sla_pct=excluded.sla_pct,
  observaciones_pct=excluded.observaciones_pct,
  recableado_pct=excluded.recableado_pct,
  vtrgar_pct=excluded.vtrgar_pct,
  estado=excluded.estado,
  origen=excluded.origen,
  actualizado_por=excluded.actualizado_por,
  actualizado_at=now();

create index if not exists ranking_legacy_snapshot_periodo_cuadrilla_idx
  on public.ranking_legacy_snapshot(periodo,cuadrilla);

create or replace view public.mv_ranking_cuadrilla_meta
with (security_invoker=true) as
select trim(cuadrilla) as cuadrilla,
  max(nullif(trim(usuario),'')) as usuario,
  max(nullif(upper(trim(sede)),'')) filter (where upper(trim(coalesce(sede,'')))<>'TODAS') as sede,
  max(nullif(upper(trim(plataforma)),'')) filter (where upper(trim(coalesce(plataforma,'')))<>'TODAS') as plataforma,
  bool_or(upper(trim(coalesce(estado,'')))='ACTIVO') as tiene_usuario_activo
from public.app_users
where nullif(trim(cuadrilla),'') is not null and upper(trim(cuadrilla))<>'TODAS'
group by trim(cuadrilla);

create or replace view public.mv_ranking_produccion_migracion
with (security_invoker=true) as
select to_char(p.fecha_ejecucion,'YYYY-MM') as periodo,
  trim(p.cuadrilla) as cuadrilla,
  max(nullif(upper(trim(p.sede)),'')) as sede,
  count(*)::integer as ordenes_elegibles,
  round(sum(coalesce(c.puntaje_consistente,1)),4) as produccion,
  count(*) filter (where c.puntaje_consistente is null)::integer as partidas_fallback_1
from public.mv_produccion_partida_motor_migracion_v1 p
left join public.mv_catalogo_puntaje_codigo c on upper(trim(c.codigo))=upper(trim(p.partida_motor))
where p.elegible_produccion_efectiva is true and p.fecha_ejecucion is not null
  and nullif(trim(p.cuadrilla),'') is not null
group by 1,2;

create or replace view public.mv_ranking_observaciones_migracion
with (security_invoker=true) as
with base as (
  select case
    when trim(coalesce(periodo_texto,'')) ~ '^20[0-9]{2}-[0-9]{2}$' then trim(periodo_texto)
    when lower(trim(coalesce(periodo_texto,''))) like 'julio %' then substring(trim(periodo_texto) from '[0-9]{4}')||'-07'
    when lower(trim(coalesce(periodo_texto,''))) like 'agosto %' then substring(trim(periodo_texto) from '[0-9]{4}')||'-08'
    when lower(trim(coalesce(periodo_texto,''))) like 'septiembre %'
      or lower(trim(coalesce(periodo_texto,''))) like 'setiembre %'
      then substring(trim(periodo_texto) from '[0-9]{4}')||'-09'
    else to_char(fecha_registro,'YYYY-MM') end as periodo,
    trim(cuadrilla) as cuadrilla,
    upper(trim(coalesce(estado,''))) as estado,
    coalesce(monto,0)::numeric as monto
  from public.economico_observaciones_snapshot
  where nullif(trim(cuadrilla),'') is not null
), calc as (
  select *, case when estado in ('SUBSANADO','ANULADO') then 0.20::numeric else 1.00::numeric end as factor_afectacion
  from base
)
select periodo,cuadrilla,count(*)::integer as observaciones,round(sum(monto),2) as monto_total,
  round(sum(monto*factor_afectacion),2) as monto_afectado
from calc group by periodo,cuadrilla;

create or replace view public.mv_ranking_universo_migracion
with (security_invoker=true) as
with periodos as (
  select periodo from public.ranking_configuracion_motor where upper(estado)='ACTIVO'
), candidatos as (
  select p.periodo,m.cuadrilla from periodos p join public.mv_ranking_cuadrilla_meta m on m.tiene_usuario_activo
  union select p.periodo,p.cuadrilla from public.mv_ranking_produccion_migracion p join periodos x on x.periodo=p.periodo
  union select e.periodo,e.cuadrilla from public.mv_efectividad_migracion e join periodos x on x.periodo=e.periodo
  union select r.periodo,r.cuadrilla from public.mv_recableado_migracion r join periodos x on x.periodo=r.periodo
  union select v.periodo,v.cuadrilla from public.mv_vtr_gar_indicador_migracion v join periodos x on x.periodo=v.periodo
  union select s.periodo,s.cuadrilla from public.mv_sla_resumen_actual_v323 s join periodos x on x.periodo=s.periodo
  union select o.periodo,o.cuadrilla from public.mv_ranking_observaciones_migracion o join periodos x on x.periodo=o.periodo
)
select periodo,trim(cuadrilla) as cuadrilla from candidatos
where nullif(trim(cuadrilla),'') is not null and upper(trim(cuadrilla))<>'TODAS';

create or replace view public.mv_ranking_componentes_migracion
with (security_invoker=true) as
select u.periodo,u.cuadrilla,
  coalesce(m.sede,p.sede,'SIN SEDE') as sede,
  coalesce(m.plataforma,case
    when upper(u.cuadrilla) like '%TRASLADO%' then 'TRASLADO'
    when upper(u.cuadrilla) like '% SGA %' then 'VISITA TECNICA'
    when upper(u.cuadrilla) like '% SGI %' then 'INSTALACION'
    else 'SIN PLATAFORMA' end) as plataforma,
  coalesce(p.produccion,0)::numeric as produccion,
  coalesce(e.efectividad,0)::numeric as efectividad,
  coalesce(r.porcentaje,0)::numeric as recableado,
  coalesce(v.porcentaje,0)::numeric as vtrgar,
  coalesce(o.observaciones,0)::integer as observaciones,
  coalesce(o.monto_total,0)::numeric as monto_total,
  coalesce(o.monto_afectado,0)::numeric as monto_afectado,
  coalesce(s.sla_bruto,0)::numeric as sla_bruto,
  coalesce(s.sla_ajustado,0)::numeric as sla_ajustado,
  coalesce(s.evaluables,0)::integer as sla_evaluables,
  greatest(coalesce(s.evaluables,0)-coalesce(s.cumplen_ajustado,0),0)::integer as sla_fuera,
  coalesce(s.excepciones_aprobadas,0)::integer as sla_excepciones_aprobadas,
  coalesce(p.ordenes_elegibles,0)::integer as produccion_ordenes,
  coalesce(p.partidas_fallback_1,0)::integer as produccion_fallback_1
from public.mv_ranking_universo_migracion u
left join public.mv_ranking_cuadrilla_meta m on m.cuadrilla=u.cuadrilla
left join public.mv_ranking_produccion_migracion p on p.periodo=u.periodo and p.cuadrilla=u.cuadrilla
left join public.mv_efectividad_migracion e on e.periodo=u.periodo and e.cuadrilla=u.cuadrilla
left join public.mv_recableado_migracion r on r.periodo=u.periodo and r.cuadrilla=u.cuadrilla
left join public.mv_vtr_gar_indicador_migracion v on v.periodo=u.periodo and v.cuadrilla=u.cuadrilla
left join public.mv_ranking_observaciones_migracion o on o.periodo=u.periodo and o.cuadrilla=u.cuadrilla
left join public.mv_sla_resumen_actual_v323 s on s.periodo=u.periodo and s.cuadrilla=u.cuadrilla;

create or replace view public.mv_ranking_motor_migracion
with (security_invoker=true) as
with b as (
 select c.*,cfg.produccion_pct,cfg.efectividad_pct,cfg.sla_pct,cfg.observaciones_pct,cfg.recableado_pct,cfg.vtrgar_pct,
   max(c.produccion) over(partition by c.periodo) max_produccion,
   max(c.recableado) over(partition by c.periodo) max_recableado,
   max(c.vtrgar) over(partition by c.periodo) max_vtrgar,
   max(c.monto_afectado) over(partition by c.periodo) max_monto_afectado
 from public.mv_ranking_componentes_migracion c
 join public.ranking_configuracion_motor cfg on cfg.periodo=c.periodo and upper(cfg.estado)='ACTIVO'
), s as (
 select *,
   case when max_produccion>0 then produccion/max_produccion*100 else 0 end score_produccion,
   case when abs(efectividad)<=1 then efectividad*100 else efectividad end score_efectividad,
   case when max_recableado>0 then 100-(recableado/max_recableado*100) else 100 end score_recableado,
   case when max_vtrgar>0 then 100-(vtrgar/max_vtrgar*100) else 100 end score_vtrgar,
   case when max_monto_afectado>0 then 100-(monto_afectado/max_monto_afectado*100) else 100 end score_observaciones,
   sla_ajustado score_sla
 from b
), p as (
 select *,
   round((score_produccion*produccion_pct/100+score_efectividad*efectividad_pct/100+score_sla*sla_pct/100+
          score_observaciones*observaciones_pct/100+score_recableado*recableado_pct/100+
          score_vtrgar*vtrgar_pct/100)::numeric,4) puntaje_final,
   round((score_sla*sla_pct/100)::numeric,4) aporte_sla,
   jsonb_build_object('PRODUCCION',produccion_pct,'EFECTIVIDAD',efectividad_pct,'SLA',sla_pct,
     'OBSERVACIONES',observaciones_pct,'RECABLEADO',recableado_pct,'VTRGAR',vtrgar_pct) pesos_json
 from s
), r as (
 select *,
   row_number() over(partition by periodo order by puntaje_final desc,produccion desc,cuadrilla asc)::integer puesto_region,
   row_number() over(partition by periodo,sede order by puntaje_final desc,produccion desc,cuadrilla asc)::integer puesto_sede,
   row_number() over(partition by periodo,plataforma order by puntaje_final desc,produccion desc,cuadrilla asc)::integer puesto_plataforma
 from p
)
select *,
 case puesto_region when 1 then '🥇' when 2 then '🥈' when 3 then '🥉' else '' end medalla_region,
 case puesto_sede when 1 then '🥇' when 2 then '🥈' when 3 then '🥉' else '' end medalla_sede,
 case puesto_plataforma when 1 then '🥇' when 2 then '🥈' when 3 then '🥉' else '' end medalla_plataforma
from r;

create or replace view public.mv_ranking_configuracion_comparacion
with (security_invoker=true) as
select coalesce(p.periodo,m.periodo) periodo,
 p.produccion_pct productivo_produccion,m.produccion_pct motor_produccion,
 p.efectividad_pct productivo_efectividad,m.efectividad_pct motor_efectividad,
 p.sla_pct productivo_sla,m.sla_pct motor_sla,
 p.observaciones_pct productivo_observaciones,m.observaciones_pct motor_observaciones,
 p.recableado_pct productivo_recableado,m.recableado_pct motor_recableado,
 p.vtrgar_pct productivo_vtrgar,m.vtrgar_pct motor_vtrgar,
 case when p.periodo is null then 'SOLO_MOTOR'
      when m.periodo is null then 'SOLO_PRODUCTIVO'
      when p.produccion_pct=m.produccion_pct and p.efectividad_pct=m.efectividad_pct and p.sla_pct=m.sla_pct
       and p.observaciones_pct=m.observaciones_pct and p.recableado_pct=m.recableado_pct and p.vtrgar_pct=m.vtrgar_pct
      then 'IGUAL' else 'DIFERENTE' end estado_comparacion
from public.ranking_configuracion_productiva_snapshot p
full join public.ranking_configuracion_motor m using(periodo);

create or replace view public.mv_ranking_conciliacion_legacy
with (security_invoker=true) as
select coalesce(l.periodo,m.periodo) periodo,coalesce(l.cuadrilla,m.cuadrilla) cuadrilla,
 l.produccion legacy_produccion,m.produccion motor_produccion,
 l.efectividad legacy_efectividad,m.efectividad motor_efectividad,
 l.recableado legacy_recableado,m.recableado motor_recableado,
 l.vtrgar legacy_vtrgar,m.vtrgar motor_vtrgar,
 l.monto_afectado legacy_monto_afectado,m.monto_afectado motor_monto_afectado,
 l.sla_ajustado legacy_sla_ajustado,m.sla_ajustado motor_sla_ajustado,
 l.puntaje_final legacy_puntaje_final,m.puntaje_final motor_puntaje_final,
 case when l.cuadrilla is null then 'SOLO_MOTOR'
      when m.cuadrilla is null then 'SOLO_LEGACY'
      when abs(coalesce(l.puntaje_final,0)-coalesce(m.puntaje_final,0))<0.0001 then 'PUNTAJE_IGUAL'
      else 'DIFERENTE_AUDITAR' end estado
from public.ranking_legacy_snapshot l
full join public.mv_ranking_motor_migracion m on m.periodo=l.periodo and m.cuadrilla=l.cuadrilla
where coalesce(l.periodo,m.periodo) in (select periodo from public.ranking_configuracion_motor);

create or replace view public.mv_ranking_migracion
with (security_invoker=true) as
select l.periodo,l.cuadrilla,l.sede,l.plataforma,l.produccion,l.efectividad,l.recableado,l.vtrgar,
 l.observaciones,l.monto_total,l.monto_afectado,l.sla_bruto,l.sla_ajustado,l.sla_evaluables,l.sla_fuera,
 l.sla_excepciones_aprobadas,l.aporte_sla,l.puntaje_final,l.puesto_region,l.puesto_sede,l.puesto_plataforma,
 l.medalla_region,l.medalla_sede,l.medalla_plataforma,l.pesos_json,'LEGACY_PROTEGIDO'::text origen
from public.ranking_legacy_snapshot l
where l.periodo not in (select periodo from public.ranking_configuracion_motor where upper(estado)='ACTIVO')
 and upper(trim(l.cuadrilla))<>'TODAS'
union all
select m.periodo,m.cuadrilla,m.sede,m.plataforma,m.produccion,m.efectividad,m.recableado,m.vtrgar,
 m.observaciones,m.monto_total,m.monto_afectado,m.sla_bruto,m.sla_ajustado,m.sla_evaluables,m.sla_fuera,
 m.sla_excepciones_aprobadas,m.aporte_sla,m.puntaje_final,m.puesto_region,m.puesto_sede,m.puesto_plataforma,
 m.medalla_region,m.medalla_sede,m.medalla_plataforma,m.pesos_json,'MOTOR_POSTGRESQL'::text origen
from public.mv_ranking_motor_migracion m;

alter table public.ranking_legacy_snapshot enable row level security;
alter table public.ranking_configuracion_productiva_snapshot enable row level security;
alter table public.ranking_configuracion_motor enable row level security;

revoke all on public.ranking_legacy_snapshot from anon,authenticated;
revoke all on public.ranking_configuracion_productiva_snapshot from anon,authenticated;
revoke all on public.ranking_configuracion_motor from anon,authenticated;
grant select on public.ranking_legacy_snapshot to service_role;
grant select on public.ranking_configuracion_productiva_snapshot to service_role;
grant select on public.ranking_configuracion_motor to service_role;

revoke all on public.mv_ranking_cuadrilla_meta from anon,authenticated;
revoke all on public.mv_ranking_produccion_migracion from anon,authenticated;
revoke all on public.mv_ranking_observaciones_migracion from anon,authenticated;
revoke all on public.mv_ranking_universo_migracion from anon,authenticated;
revoke all on public.mv_ranking_componentes_migracion from anon,authenticated;
revoke all on public.mv_ranking_motor_migracion from anon,authenticated;
revoke all on public.mv_ranking_configuracion_comparacion from anon,authenticated;
revoke all on public.mv_ranking_conciliacion_legacy from anon,authenticated;
revoke all on public.mv_ranking_migracion from anon,authenticated;

grant select on public.mv_ranking_cuadrilla_meta to service_role;
grant select on public.mv_ranking_produccion_migracion to service_role;
grant select on public.mv_ranking_observaciones_migracion to service_role;
grant select on public.mv_ranking_universo_migracion to service_role;
grant select on public.mv_ranking_componentes_migracion to service_role;
grant select on public.mv_ranking_motor_migracion to service_role;
grant select on public.mv_ranking_configuracion_comparacion to service_role;
grant select on public.mv_ranking_conciliacion_legacy to service_role;
grant select on public.mv_ranking_migracion to service_role;
